check "32 launch fields numeric, launch_to_top_s > launch_to_rpc_s, no monerod warm-up line" 'a=$(field "$R" launch_to_rpc_s); b=$(field "$R" launch_to_top_s); awk -v a="$a" -v b="$b" "BEGIN {exit !(a > 0 && b > a)}" && [ "$(field "$R" read_MB_launch)" -ge 0 ] && [ "$(field "$R" monerod_warmup_s)" = na ] && [ "$(field "$R" monerod_warmup_MB)" = na ]'
