FAKE_WARMTOOL_FAIL=1 WARM_DBS="spent_keys" WARM_TOOL=$W/bin/warmcheck bash "$KIT/hdd_run.sh" t33 "$W/bin/monerod" > "$W/last.out" 2>&1; rc=$?
check "33 failing tool: exit 3, ABORT warm, its output shown, monerod not started" '[ "$rc" = 3 ] && grep -q "ABORT warm: $W/bin/warmcheck failed (exit 2)" "$W/last.out" && grep -q "No such file" "$W/last.out" && ! ls "$W"/out/*-t33/monerod.log > /dev/null 2>&1'
export DATA_DIR=$W/data33b
WARM_DBS="spent_keys" WARM_TOOL=/nonexistent/warmcheck bash "$KIT/hdd_run.sh" t33b "$W/bin/monerod" > "$W/last.out" 2>&1; rc=$?
check "33 missing tool: exit 2, no restore" '[ "$rc" = 2 ] && grep -q "WARM_TOOL /nonexistent/warmcheck is not executable" "$W/last.out" && [ ! -f "$DATA_DIR/testnet/lmdb/data.mdb" ]'
# 34. v5: monerod .5's warm-up line is parsed; a 4 s startup shows in launch_to_rpc_s and launch_to_top_s, not in wall_s
