check "34 launch_to_rpc_s >= 4, launch_to_top_s >= wall_s + 3 (wall_s is in whole seconds)" 'a=$(field "$R" launch_to_rpc_s); b=$(field "$R" launch_to_top_s); w=$(field "$R" wall_s); awk -v a="$a" -v b="$b" -v w="$w" "BEGIN {exit !(a >= 4 && b >= w + 3)}"'
