check "35 exit 0, monerod_warmup_s=0.1 monerod_warmup_MB=15" '[ "$rc" = 0 ] && [ "$(field "$R" monerod_warmup_s)" = 0.1 ] && [ "$(field "$R" monerod_warmup_MB)" = 15 ]'
# 36. v5: a timeout leaves launch_to_top_s na (the top was not reached); launch_to_rpc_s is still measured
