check "36 timeout: exit 0, outcome timeout, launch_to_top_s=na, launch_to_rpc_s numeric" '[ "$rc" = 0 ] && [ "$(field "$R" outcome)" = timeout ] && [ "$(field "$R" launch_to_top_s)" = na ] && awk -v a="$(field "$R" launch_to_rpc_s)" "BEGIN {exit !(a > 0)}"'
# 38. v6: a .5-style log (one completion line at start): warm-up s and MB from it, end_s a sane number, not stopped
