check "38 .5-style: monerod_warmup_end_s between 0 and 5 (the fake logs at its start)" 'awk -v e="$(field "$R" monerod_warmup_end_s)" "BEGIN {exit !(e ~ /^[0-9]+\.[0-9]\$/ && e >= 0 && e <= 5)}"'
