check "39 B-style: monerod_warmup_end_s between 3 and 8, the summary shows the completion line" 'awk -v e="$(field "$R" monerod_warmup_end_s)" "BEGIN {exit !(e >= 3 && e <= 8)}" && grep -q "^monerod warm-up: Index warm-up: read the spent key.*in 55.3 s" "$(ls "$W"/out/*-t39/summary.txt)" && ! grep -q "^monerod warm-up: .*in the background" "$(ls "$W"/out/*-t39/summary.txt)"'
# 40. v6: a stopped warm-up: stopped=1, no completion line so warm-up s, MB and end_s are na
