FAKE_WARMUP_BG=2 FAKE_WARMUP_STOP=1 FAKE_WARMUP_LINE=unused bash "$KIT/hdd_run.sh" t40 "$W/bin/monerod" > "$W/last.out" 2>&1; rc=$?
