check "40 stopped: exit 0, stopped=1, warmup_s=na MB=na end_s=na" '[ "$rc" = 0 ] && [ "$(field "$R" monerod_warmup_stopped)" = 1 ] && [ "$(field "$R" monerod_warmup_s)" = na ] && [ "$(field "$R" monerod_warmup_MB)" = na ] && [ "$(field "$R" monerod_warmup_end_s)" = na ]'
# 43. v13: the stage 1c driver, its traced diagnosis and its scorer.
#   Fakes: monerod8 and monerod7 (the fake monerod with the version text of the .8 candidate and of the .7 release; monerod8 writes
#   "LMDB page cache drop: on" to its log file, as FAKE_CDROP_F says, monerod7 none, as FAKE_CDROP_N says; each also appends the
#   MONERODATO_NO_DROP_FREED/G016_PREFETCH variables it sees to $W/envs.log), a bpftrace that prints 1,500 bio lines and stops on SIGINT, one
#   that exits at once, and a filefrag that prints one extent.
cat > "$W/bin/monerod8" <<'EOS'
#!/bin/sh
case " $* " in *" --version "*) ;; *) echo "monerod8:$(env | grep -E '^MONERODATO_(NO_DROP_FREED|G016_PREFETCH)' | paste -sd,)" >> "$(dirname "$0")/../envs.log";; esac
FAKE_VERSION="Monero 'Fake' (v0.18.4.5-monerodato.8)" FAKE_CDROP=${FAKE_CDROP_F:-on} exec "$(dirname "$0")/monerod" "$@"
EOS
cat > "$W/bin/monerod7" <<'EOS'
#!/bin/sh
case " $* " in *" --version "*) ;; *) echo "monerod7:$(env | grep -E '^MONERODATO_(NO_DROP_FREED|G016_PREFETCH)' | paste -sd,)" >> "$(dirname "$0")/../envs.log";; esac
FAKE_VERSION="Monero 'Fake' (v0.18.4.5-monerodato.7)" FAKE_CDROP=${FAKE_CDROP_N:-none} exec "$(dirname "$0")/monerod" "$@"
EOS
cat > "$W/bin/bpftrace" <<'EOS'
#!/usr/bin/env python3
# fake bpftrace for kit v10's tests: checks its arguments (-q <script> <devt>), prints 1,500 lines in bioread_vm.bt's
# format, then waits; SIGINT or SIGTERM ends it with exit 0 (a Python handler: a shell trap cannot catch a SIGINT that a
# non-interactive shell's background job starts with ignored)
import os, signal, sys, time
if len(sys.argv) != 4 or sys.argv[1] != "-q" or not os.path.isfile(sys.argv[2]) or not sys.argv[3].isdigit():
    sys.stderr.write("fake bpftrace: bad arguments %s\n" % sys.argv[1:]); sys.exit(3)
signal.signal(signal.SIGINT, lambda *a: sys.exit(0)); signal.signal(signal.SIGTERM, lambda *a: sys.exit(0))
for i in range(1500):
    print("%d %d %d R %d 8" % (time.monotonic_ns(), os.getpid(), os.getpid(), 1000 + 8 * i))
sys.stdout.flush()
while True:
    time.sleep(0.2)
EOS
printf '#!/bin/sh\necho "ERROR: fake bpftrace refuses to attach" >&2\nexit 1\n' > "$W/bin/bpftrace_fail"
cat > "$W/bin/filefrag" <<'EOS'
#!/bin/sh
echo "Filesystem type is: ef53"
echo "File size of $2 is 52428800 (12800 blocks of 4096 bytes)"
echo " ext:     logical_offset:        physical_offset: length:   expected: flags:"
echo "   0:        0..   12799:      34816..     47615:  12800:             last,eof"
echo "$2: 1 extent found"
EOS
chmod +x "$W/bin/monerod8" "$W/bin/monerod7" "$W/bin/bpftrace" "$W/bin/bpftrace_fail" "$W/bin/filefrag"
export DATA_DIR=$W/data43; : > "$FAKE_ARGS_LOG"; : > "$FAKE_SUDO_LOG"; : > "$W/envs.log"
