#   MONERODATO_G016_PREFETCH_MAX in monerod's environment, even when the caller has them
MONERODATO_NO_DROP_FREED=1 MONERODATO_G016_PREFETCH_BLOCKS=0 MONERODATO_G016_PREFETCH_MAX=77 TARGET_TOP=3106420 BIN_F=$W/bin/monerod8 BIN_N=$W/bin/monerod7 bash "$KIT/hdd_stage1c.sh" > "$W/stage1c_nocap.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1); STN=$ST
check "43a no-cap stage1c exit 0, STAGE1C_DONE, 4 RESULT lines r1-F r1-N r2-N r2-F, each mem_max=none" '[ "$rc" = 0 ] && grep -q STAGE1C_DONE "$W/stage1c_nocap.out" && [ "$(grep "^RESULT" "$ST/results.txt" | grep -oE "label=[^ ]+" | paste -sd,)" = "label=r1-F,label=r1-N,label=r2-N,label=r2-F" ] && [ "$(grep "^RESULT" "$ST/results.txt" | grep -c " mem_max=none ")" = 4 ]'
check "43a CACHEDROP lines: F on=1 lines=1 reason=na; N on=0 lines=0 reason=na; no DROP or PREFETCH line" '[ "$(grep "^CACHEDROP" "$ST/results.txt" | paste -sd,)" = "CACHEDROP label=r1-F arm=F on=1 lines=1 reason=na,CACHEDROP label=r1-N arm=N on=0 lines=0 reason=na,CACHEDROP label=r2-N arm=N on=0 lines=0 reason=na,CACHEDROP label=r2-F arm=F on=1 lines=1 reason=na" ] && ! grep -qE "^(DROP|PREFETCH) " "$ST/results.txt"'
check "43a the log's done lines show cache drop on=1 for F and on=0 for N" '[ "$(grep -c "^done round .* arm F: .* cache drop on=1$" "$ST/log.txt")" = 2 ] && [ "$(grep -c "^done round .* arm N: .* cache drop on=0$" "$ST/log.txt")" = 2 ]'
check "43a monerod ran 4 times (F twice, N twice) with none of the three variables, although the caller set them" '[ "$(grep -c "^monerod8:$" "$W/envs.log")" = 2 ] && [ "$(grep -c "^monerod7:$" "$W/envs.log")" = 2 ] && [ "$(wc -l < "$W/envs.log")" = 4 ]'
check "43a every run reached 3,106,420 with its hash; no TRACE line, no trace directory, no bpftrace call" '[ "$(grep "^RESULT" "$ST/results.txt" | grep -c "hash_at_3106420=$(printf %064x 3106420)")" = 4 ] && ! grep -q "^TRACE" "$ST/results.txt" && ! ls -d "$ST"/trace-* > /dev/null 2>&1 && ! grep -q bpftrace "$FAKE_SUDO_LOG"'
check "43a the log names BIN_F and BIN_N with their versions, the run script and the trace script" 'grep -q "^BIN_F $W/bin/monerod8 ([0-9a-f]\{16\}) Monero .Fake. (v0.18.4.5-monerodato.8)$" "$ST/log.txt" && grep -q "^BIN_N $W/bin/monerod7 ([0-9a-f]\{16\}) Monero .Fake. (v0.18.4.5-monerodato.7)$" "$ST/log.txt" && ! grep -q "^BIN_3" "$ST/log.txt" && grep -q "^run script .*hdd_run.sh (" "$ST/log.txt" && grep -q "trace script .*hdd_trace.sh (" "$ST/log.txt"'
sleep 1
# 43b. the diagnosis: 1 round of W V, traced, with the page-event log
TARGET_TOP=3106420 ROUNDS=1 ARMS="W V" BIN_3EWL=$W/bin/monerod BIN_3FWL=$W/bin/monerod bash "$KIT/hdd_stage1c.sh" > "$W/stage1c_diag.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1); STD=$ST
check "43b diagnosis exit 0, its own directory, RESULT lines r1-W r1-V, CACHEDROP on=0 lines=0 on both" '[ "$rc" = 0 ] && [ "$ST" != "$STN" ] && [ "$(grep "^RESULT" "$ST/results.txt" | grep -oE "label=[^ ]+" | paste -sd,)" = "label=r1-W,label=r1-V" ] && [ "$(grep "^CACHEDROP" "$ST/results.txt" | paste -sd,)" = "CACHEDROP label=r1-W arm=W on=0 lines=0 reason=na,CACHEDROP label=r1-V arm=V on=0 lines=0 reason=na" ]'
check "43b two TRACE lines: 1,500 bio lines, 1 extent, partstart a number, a node pid, rc 0, the page-event log counted" '[ "$(grep -c "^TRACE label=r1-[WV] pid=[0-9][0-9]* bio_lines=1500 node_reads=0 samples=[0-9][0-9]* fiemap_extents=1 partstart=[0-9][0-9]* wlog=W:1200,F:1200,D:1200,C:1200 rc=0 dir=$ST/trace-r1-[WV]$" "$ST/results.txt")" = 2 ]'
check "43b each trace dir has bio.txt, samples.csv (header and rows), fiemap.txt, the log, run.log with the node pid and mono0" 'ok=1; for a in W V; do T=$ST/trace-r1-$a; [ "$(wc -l < $T/bio.txt)" = 1500 ] && [ "$(head -1 $T/samples.csv)" = "mono_ns,unix_s,height,cpu_ticks" ] && [ "$(wc -l < $T/samples.csv)" -ge 2 ] && grep -q "last,eof" $T/fiemap.txt && [ "$(grep -c "^W " $T/g016_wlog.txt)" = 1200 ] && grep -qE "^test node pid [0-9]+, mono0 [0-9]+, partstart [0-9]+$" $T/run.log || ok=0; done; [ $ok = 1 ]'
check "43b bpftrace started through sudo with the script and a device number, stopped with SIGINT; none left running" '[ "$(grep -c "fake sudo: -n sh -c .* bpftrace $(realpath "$KIT")/bioread_vm.bt [0-9][0-9]*$" "$FAKE_SUDO_LOG")" = 2 ] && [ "$(grep -c "fake sudo: -n kill -INT [0-9]" "$FAKE_SUDO_LOG")" = 2 ] && ! pgrep -u "$(id -u)" -f "bpftrace -q" > /dev/null && ! grep -q "bpftrace killed" "$ST"/trace-r1-*/run.log'
check "43b the sampler's heights come from the fake node (3,106,4xx)" 'grep -qE "^[0-9]+,[0-9.]+,31064[0-9][0-9],[0-9]+$" "$ST"/trace-r1-W/samples.csv'
sleep 1
# 43c. the capped stage: 2 rounds of F N at MEM_MAX=1536M
MEM_MAX=1536M TARGET_TOP=3106420 BIN_F=$W/bin/monerod8 BIN_N=$W/bin/monerod7 bash "$KIT/hdd_stage1c.sh" > "$W/stage1c_cap.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1); STC=$ST
check "43c capped stage1c exit 0, 4 RESULT lines with mem_max=1536M in the order r1-F r1-N r2-N r2-F" '[ "$rc" = 0 ] && [ "$ST" != "$STD" ] && [ "$(grep "^RESULT" "$ST/results.txt" | grep -c " mem_max=1536M ")" = 4 ] && [ "$(grep "^RESULT" "$ST/results.txt" | grep -oE "label=[^ ]+" | paste -sd,)" = "label=r1-F,label=r1-N,label=r2-N,label=r2-F" ]'
check "43c CACHEDROP: F on=1 lines=1, N on=0 lines=0, in run order" '[ "$(grep "^CACHEDROP" "$ST/results.txt" | grep -oE "arm=[FN] on=[01] lines=[0-9]+" | paste -sd,)" = "arm=F on=1 lines=1,arm=N on=0 lines=0,arm=N on=0 lines=0,arm=F on=1 lines=1" ]'
# 43d. the scorer on the three files
python3 -I "$KIT/stage1c_table.py" "$STN/results.txt" "$STD/results.txt" "$STC/results.txt" > "$W/score43.txt" 2>&1
check "43d the scorer: 2 F and 2 N runs at each level, 1 W and 1 V, no PROBLEM line" 'grep -q "^level 1536M arm F: runs 2;" "$W/score43.txt" && grep -q "^level none arm N: runs 2;" "$W/score43.txt" && grep -q "^diagnosis arm W: runs 1;" "$W/score43.txt" && grep -q "^diagnosis arm V: runs 1;" "$W/score43.txt" && ! grep -q "^PROBLEM" "$W/score43.txt"'
check "43d the scorer: per-run table has the cdrop column, on for F, na for N; E5 has no per-run complaint (stage incomplete only: the fake runs are short)" 'grep -qE "cdrop +hash$" "$W/score43.txt" && grep -E "^(none|1536M) +r1-F " "$W/score43.txt" | grep -q " on  *[A-Za-z]*$" && grep -E "^(none|1536M) +r1-N " "$W/score43.txt" | grep -q " na  *[A-Za-z]*$" && grep -q "^E5 NOT met: stage incomplete$" "$W/score43.txt"'
check "43d the scorer: E10 met (BIN_F .8, BIN_N .7, different sha16, read from the stage logs)" 'grep -q "^E10 met: " "$W/score43.txt"'
check "43d the scorer: E8 not met on the samples (a 2 s fake run), the extents and log fine; E1 and E7 incomplete; investigate; diagnosis incomplete" 'grep -q "^E8 NOT met: .*samples" "$W/score43.txt" && ! grep "^E8" "$W/score43.txt" | grep -q "fiemap_extents\|page-event log" && grep -q "^E1 NOT met: capped stage incomplete" "$W/score43.txt" && grep -q "^E7 NOT met: no-cap stage incomplete" "$W/score43.txt" && grep -q "^DECISION investigate" "$W/score43.txt" && grep -q "^DIAGNOSIS incomplete" "$W/score43.txt"'
python3 -I "$KIT/stage1c_table.py" "$STN/results.txt" "$STC/results.txt" > "$W/score43fn.txt" 2>&1
check "43d the scorer on the F/N files alone: E8 and E9 not run, no DIAGNOSIS line, no PROBLEM line" 'grep -qx "E8 not run: no traced stage in this kit" "$W/score43fn.txt" && grep -qx "E9 not run: no traced stage in this kit" "$W/score43fn.txt" && ! grep -q DIAGNOSIS "$W/score43fn.txt" && ! grep -q "^PROBLEM" "$W/score43fn.txt"'
mv "$STN/log.txt" "$STN/log.txt.off"
python3 -I "$KIT/stage1c_table.py" "$STN/results.txt" "$STC/results.txt" > "$W/score43nolog.txt" 2>&1
mv "$STN/log.txt.off" "$STN/log.txt"
check "43d the scorer with one stage's log.txt missing: E10 not met, naming the file" 'grep -q "^E10 NOT met: .*log.txt missing" "$W/score43nolog.txt"'
# 43g. the cache drop line is read from the run's monerod.log: an off line with a reason, a second line, and an N run that logs one
TARGET_TOP=3106420 ROUNDS=1 ARMS=F FAKE_CDROP_F=off BIN_F=$W/bin/monerod8 bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1)
check "43g off line: arm F alone runs (no BIN_N needed), exit 0, CACHEDROP on=0 lines=1 reason=no_cachestat_available, done line on=0" '[ "$rc" = 0 ] && [ "$(grep "^CACHEDROP" "$ST/results.txt")" = "CACHEDROP label=r1-F arm=F on=0 lines=1 reason=no_cachestat_available" ] && grep -q "arm F: .* cache drop on=0$" "$ST/log.txt"'
sleep 1
TARGET_TOP=3106420 ROUNDS=1 ARMS=N FAKE_CDROP_N=on BIN_N=$W/bin/monerod7 bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1)
check "43g N that logs a cache drop line: CACHEDROP on=1 lines=1 (the scorer calls it E5), exit 0" '[ "$rc" = 0 ] && [ "$(grep "^CACHEDROP" "$ST/results.txt")" = "CACHEDROP label=r1-N arm=N on=1 lines=1 reason=na" ]'
sleep 1
# 43e. bad arguments: no stage directory
n0=$(ls -d "$W"/out/stage1c-* | wc -l)
BIN_F=$W/bin/monerod8 BIN_N=$W/bin/monerod7 ARMS="F X" bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
check "43e unknown arm X: exit 2, no stage directory" '[ "$rc" = 2 ] && grep -q "unknown arm X" "$W/last.out" && [ "$(ls -d "$W"/out/stage1c-* | wc -l)" = "$n0" ]'
BIN_F=$W/bin/nonexistent BIN_N=$W/bin/monerod7 bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
check "43e BIN_F not executable: exit 2" '[ "$rc" = 2 ] && grep -q "BIN_F .* is not executable (arm F)" "$W/last.out" && [ "$(ls -d "$W"/out/stage1c-* | wc -l)" = "$n0" ]'
BIN_F=$W/bin/monerod8 bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
check "43e BIN_N unset with arms F N: exit 2" '[ "$rc" = 2 ] && grep -q "BIN_N (unset) is not executable (arm N)" "$W/last.out" && [ "$(ls -d "$W"/out/stage1c-* | wc -l)" = "$n0" ]'
BIN_3H=$W/bin/monerod8 BIN_3G=$W/bin/monerod8 BIN_3F=$W/bin/monerod8 bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
check "43e the old BIN_3H/BIN_3G/BIN_3F names are no fallback: exit 2, BIN_F (unset)" '[ "$rc" = 2 ] && grep -q "BIN_F (unset) is not executable (arm F)" "$W/last.out" && [ "$(ls -d "$W"/out/stage1c-* | wc -l)" = "$n0" ]'
ARMS="W" bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
check "43e arm W without BIN_3EWL: exit 2" '[ "$rc" = 2 ] && grep -q "BIN_3EWL (unset) is not executable (arm W)" "$W/last.out" && [ "$(ls -d "$W"/out/stage1c-* | wc -l)" = "$n0" ]'
# 43f. bpftrace cannot start: the traced run aborts before hdd_run.sh, and the stage stops
nr0=$(ls -d "$W"/out/*-r1-W 2> /dev/null | wc -l)
BPFTRACE=bpftrace_fail TARGET_TOP=3106420 ROUNDS=1 ARMS="W" BIN_3EWL=$W/bin/monerod bash "$KIT/hdd_stage1c.sh" > "$W/last.out" 2>&1; rc=$?
ST=$(ls -d "$W"/out/stage1c-* | tail -1)
check "43f bpftrace fails: exit 1, STAGE1C_ABORT, TRACE_ABORT logged, no run directory for it, no RESULT" '[ "$rc" = 1 ] && grep -q "STAGE1C_ABORT round 1 arm W" "$W/last.out" && grep -q "TRACE_ABORT" "$ST/trace-r1-W/run.log" && [ "$(ls -d "$W"/out/*-r1-W 2> /dev/null | wc -l)" = "$nr0" ] && [ ! -s "$ST/results.txt" ]'
echo "TOTAL pass=$pass fail=$fail"
[ "$fail" = 0 ]
